#[derive(sqlx::Type)] #[sqlx(rename_all = "lowercase")] // VARCHAR/TEXT discriminator
enum Kind { Engineer, Manager }
struct EmployeeRow { id: i64, name: String, kind: Kind, language: Option<String>, reports: Option<i32> }

fn into_employee(r: EmployeeRow) -> Result<Employee, MappingError> {
    match (r.kind, r.language, r.reports) {
        (Kind::Engineer, Some(language), _) => Ok(Employee::Engineer { id: r.id, name: r.name, language }),
        (Kind::Manager, _, Some(reports)) => Ok(Employee::Manager { id: r.id, name: r.name, reports }),
        _ => Err(MappingError::DiscriminatorMismatch),
    }
}
